head.script:
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};

scwin.onpageload = function () {
    var d = new Date();
    var strToday = d.getFullYear() + ("0" + (d.getMonth() + 1)).slice(-2) + ("0" + d.getDate()).slice(-2);
    dlt_schedule.setJSON([{ "id" : "S1", "title" : "일정", "start" : strToday, "end" : strToday }]);
    target.setDisabled(true);
    dlt_schedule2.setJSON([{ "id" : "S1", "title" : "일정", "start" : strToday, "end" : strToday }]);
    target2.setReadOnly(true);
};

scwin.target_onclick = function (dateInfo) {
    var strTarget = (dateInfo.type === "event") ? "일정" : "날짜 " + WebSquare.date.getFormattedDate(dateInfo.start, "yyyy-MM-dd");
    scwin.setReturnValue("onclick 발생 : " + strTarget);
};

scwin.target2_onmoveschedule = function (info) {
    scwin.setReturnValue("onmoveschedule 발생 : start " + info.oldObj.start + " → " + info.newObj.start + ", end " + info.oldObj.end + " → " + info.newObj.end + ", rowStatus " + dlt_schedule2.getRowStatus(info.rowIndex));
};

scwin.target2_onaddschedule = function (info) {
    scwin.setReturnValue("onaddschedule 발생 : start " + info.newObj.start + ", rowStatus " + dlt_schedule2.getRowStatus(info.rowIndex));
};
